import time
from laya import Router

router = Router()

question = {
    "churn_risk": {
        "type": "noul",
        "instructions": "Does the user threaten to cancel?",
    },
}

english = {"body": "Refund the duplicate today or we cancel our plan."}
hindi = {"body": "आज ही पैसे वापस करें, वरना हम प्लान रद्द कर देंगे।"}

# build both checkpoints first, so the times below are decisions, not downloads
router.predict(english, question)
router.predict(hindi, question)
print("both checkpoints loaded\n")

for name, state in (("english", english), ("hindi  ", hindi)):
    t = time.perf_counter()
    res = router.predict(state, question)
    ms = (time.perf_counter() - t) * 1000
    print("%s  ->  %-12s  churn %.3f   %3.0f ms" % (
        name, res["routing"]["model"], res["answers"]["churn_risk"]["noul"], ms))

print("\nwhy it chose that, without running the model:")
for state in (english, hindi):
    t = time.perf_counter()
    d = router.route(state)
    print("  %-12s  %.2f ms  %s" % (d.model, (time.perf_counter() - t) * 1000, d.reason))
